parameters.jsCode:
const res = $input.first().json;
const orgs = res.organizations || res.accounts || [];
const leads = orgs.map(o => ({
  name: o.name,
  city: o.city || '',
  state: o.state || '',
  country: o.country || '',
  phone: o.phone || (o.primary_phone && o.primary_phone.number) || '',
  email: '',
  web: o.website_url || '',
  type: 'Distributor',
  focus: '[AUTO] ' + ((o.industry || 'footwear wholesale/distribution')) + (o.estimated_num_employees ? ' · ~' + o.estimated_num_employees + ' staff' : '')
}));
return [{ json: { leads } }];
